const HeaderLogoComponent = class {
  constructor(hostRef) {
    registerInstance(this, hostRef);
    this.logo = '8451';
    this.appname = undefined;
    this.href = undefined;
    this.target = undefined;
    this.route = undefined;
    this.widerlogo = false;
  }
  handleKeyDown(ev) {
    const target = ev.target;
    if (ev.key === ' ' || ev.key === 'Enter') {
      target.click();
      MdsEventUtility.cancelEvent(ev);
    }
  }
  getAppName(app) {
    return (app === MdsHeaderLogoTypeEnum.e451 ||
      app === MdsHeaderLogoTypeEnum.kroger) &&
      this.appname ? (h("mds-text", { size: "lg", tag: "strong", color: MdsTextColorEnum.ink_primary }, this.appname)) : null;
  }
  getTitle(app) {
    if (app === MdsHeaderLogoTypeEnum.stratum) {
      return '84.51° Stratum';
    }
    else if (app === MdsHeaderLogoTypeEnum.prism) {
      return '84.51° Prism';
    }
    else if (app === MdsHeaderLogoTypeEnum.edna) {
      return '84.51° EDNA';
    }
    else if (app === MdsHeaderLogoTypeEnum.kroger) {
      return 'Kroger';
    }
    else {
      return '84.51°';
    }
  }
  render() {
    return (h(Host, { slot: "logo" }, h("a", { href: MdsNavigationUtility.getHref(this.href, this.route), target: this.target, rel: "noopener noreferrer", onClick: (event) => MdsNavigationUtility.handleAnchorClick(event, this.route, this.href, this.target, true), class: {
        'mds-header-logo': true,
        'mds-header-logo--prism': this.logo === MdsHeaderLogoTypeEnum.prism,
        'mds-header-logo--stratum': this.logo === MdsHeaderLogoTypeEnum.stratum,
        'mds-header-logo--edna': this.logo === MdsHeaderLogoTypeEnum.edna,
        'mds-header-logo--polaris': this.logo === MdsHeaderLogoTypeEnum.polaris,
        'mds-header-logo--data-direct': this.logo === MdsHeaderLogoTypeEnum.data_direct,
        'mds-header-logo--data-direct-data-orders': this.logo === MdsHeaderLogoTypeEnum.data_direct_data_orders,
        'mds-header-logo--kroger': this.logo === MdsHeaderLogoTypeEnum.kroger,
        'mds-header-logo--generic': this.logo === MdsHeaderLogoTypeEnum.e451,
      }, title: this.getTitle(this.logo) }, h("div", { class: "mds-header-logo__inner" }, h("div", { class: {
        'mds-header-logo__art': !this.widerlogo,
        'mds-header-logo__art--wider': !!this.widerlogo,
      } }), this.getAppName(this.logo)))));
  }
  get hostElement() { return getElement(this); }
};
HeaderLogoComponent.style = headerLogoCss;

export { HeaderLogoComponent as mds_header_logo };
